)

count(
  (
      max by (test_id, vcs_repository_name, server_version) (
        quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent])
      )
    /
      clamp_min(
        max by (test_id, vcs_repository_name, server_version) (
          quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent)
        ),
        0.05
      )
  ) > $ratio
  and
  (
      max by (test_id, vcs_repository_name, server_version) (
        quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$recent])
      )
    -
      max by (test_id, vcs_repository_name, server_version) (
        quantile_over_time(0.5, cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent)
      )
  ) > 1
  and
    max by (test_id, vcs_repository_name, server_version) (
      count_over_time(cae_v16_test_duration_seconds{vcs_repository_name=~"$repository", server_version=~"$server_version", vcs_repository_ref_name=~"$branch"}[$baseline] offset $recent)
    ) >= 10
)
or vector(0)

